  const fly = req.headers['fly-client-ip'];   // posé par le proxy Fly
  if (fly) return String(fly).trim();
  const xff = String(req.headers['x-forwarded-for'] || '').split(',').pop().trim();   // dernier saut = proxy
  return xff || req.socket.remoteAddress || '';
